/* dispatch loop: one choke point before any route handler */
struct principal p;
if (!route_is_public(req->path)) {              /* default: protected */
    if (auth_enforcer(&p, req) != 0) {          /* delegates to the verifier */
        return send_challenge(req, 401);        /* WWW-Authenticate */
    }
    req->principal = p;                         /* request-scoped storage */
}
return route_handler(req);
